    { const char * tb_v1276 = "    uint64_t t = tb_ksym_tab;\n"; *(const char * *)tb_grow(v_lines) = tb_v1276; }
    { const char * tb_v1277 = "    long long lo = 0, hi = (long long)tb_ksym_n - 1, len = (long long)strlen(nm);\n"; *(const char * *)tb_grow(v_lines) = tb_v1277; }
    { const char * tb_v1278 = "    if (t <= 1) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1278; }
