    { const char * tb_v1528 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1528; }
    { const char * tb_v1529 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1529; }
