    { const char * tb_v1557 = "// код пробуждения: копируется в 0x8000; адреса внутри считаются от 0x8000\n"; *(const char * *)tb_grow(v_lines) = tb_v1557; }
    { const char * tb_v1558 = "extern char tb_tramp[], tb_tramp_end[];\n"; *(const char * *)tb_grow(v_lines) = tb_v1558; }
