    { const char * tb_v1943 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1943; }
    { const char * tb_v1944 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1944; }
