    { const char * tb_v2158 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; tb_u8c_clear(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2158; }
    { const char * tb_v2159 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2159; }
    { const char * tb_v2160 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2160; }
    { const char * tb_v2161 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2161; }
    { const char * tb_v2162 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2162; }
    { const char * tb_v2163 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v2163; }
    { const char * tb_v2164 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2164; }
    { const char * tb_v2165 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2165; }
    { const char * tb_v2166 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v2166; }
    { const char * tb_v2167 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2167; }
    { const char * tb_v2168 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v2168; }
    { const char * tb_v2169 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2169; }
    { const char * tb_v2170 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v2170; }
    { const char * tb_v2171 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2171; }
    { const char * tb_v2172 = "TB_INL void tb_temp_end_p(tb_mark *m) { tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2172; }
    { const char * tb_v2173 = "// память функции: своя область, только если функцию позвали не изнутри другой области\n"; *(const char * *)tb_grow(v_lines) = tb_v2173; }
    { const char * tb_v2174 = "TB_INL int tb_fa_begin(tb_mark *m) { if (tb_temp_depth != 0) return 0; *m = tb_temp_begin(); return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2174; }
    { const char * tb_v2175 = "TB_INL void tb_fa_end(int fa, tb_mark *m) { if (fa) tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2175; }
    { const char * tb_v2176 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
    { const char * tb_v2178 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
    { const char * tb_v2180 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v2180; }
    { const char * tb_v2181 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v2181; }
    { const char * tb_v2182 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v2182; }
    { const char * tb_v2183 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v2183; }
    { const char * tb_v2184 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v2184; }
    { const char * tb_v2185 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v2185; }
    { const char * tb_v2186 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2186; }
    { const char * tb_v2187 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2187; }
    { const char * tb_v2188 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2188; }
    { const char * tb_v2189 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2189; }
    { const char * tb_v2190 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2190; }
    { const char * tb_v2191 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2191; }
    { const char * tb_v2192 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2192; }
    { const char * tb_v2193 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2193; }
    { const char * tb_v2194 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2194; }
    { const char * tb_v2195 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2195; }
    { const char * tb_v2196 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2196; }
    { const char * tb_v2197 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2197; }
    { const char * tb_v2198 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2198; }
    { const char * tb_v2199 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2199; }
    { const char * tb_v2200 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v2200; }
    { const char * tb_v2201 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2201; }
    { const char * tb_v2202 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2202; }
    { const char * tb_v2203 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2203; }
    { const char * tb_v2204 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v2204; }
    { const char * tb_v2205 = "#define TB_GNC 37\n"; *(const char * *)tb_grow(v_lines) = tb_v2205; }
    { const char * tb_v2206 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
    { const char * tb_v2208 = "TB_API const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v2208; }
    { const char * tb_v2209 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v2209; }
    { const char * tb_v2210 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v2210; }
    { const char * tb_v2211 = "typedef struct tb_gpage {\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "    char *start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
    { const char * tb_v2213 = "    long long bsize, nblocks;      // мелкие: размер блока и сколько их\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
    { const char * tb_v2214 = "    long long nbytes, cap;         // большой блок: сколько занято и сколько взято\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "    unsigned long long inv;        // 2^32 / bsize (вверх): номер блока умножением, без деления\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
    { const char * tb_v2216 = "    int large, cls, in_avail, np;  // np: внутри нет адресов (числа, тексты) — обход туда не смотрит\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "    unsigned char *fl;             // по байту на блок: 1 — занят, 2 — нужен (найден при обходе)\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "    unsigned char lfl;             // то же для большого блока\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
    { const char * tb_v2219 = "    void *free; long long nfree, bump;   // bump: блоки с этого номера ещё ни разу не брали (там нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v2219; }
    { const char * tb_v2220 = "    struct tb_gpage *next, *prev, *anext;\n"; *(const char * *)tb_grow(v_lines) = tb_v2220; }
    { const char * tb_v2221 = "} tb_gpage;\n"; *(const char * *)tb_grow(v_lines) = tb_v2221; }
    { const char * tb_v2222 = "typedef struct { char *p; long long n; } tb_grange;\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
    { const char * tb_v2223 = "TB_API unsigned char tb_gcls[TB_GBIG / 8 + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "TB_API tb_gpage *tb_gall = 0, *tb_glarge = 0, *tb_gavail[2][TB_GNC];\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
    { const char * tb_v2227 = "TB_API uintptr_t tb_glo = ~(uintptr_t)0, tb_ghi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2227; }
    { const char * tb_v2228 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2228; }
    { const char * tb_v2229 = "TB_API int tb_gready = 0, tb_goff = 0, tb_gstats = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2229; }
    { const char * tb_v2230 = "TB_API char *tb_gtop = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "TB_API pthread_mutex_t tb_glock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "TB_API tb_grange *tb_groots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "TB_API long long tb_gnroots = 0, tb_gcaproots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
    { const char * tb_v2234 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "TB_API void tb_gsetup(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "    int c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
    { const char * tb_v2237 = "    for (long long i = 0; i <= TB_GBIG / 8; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2237; }
    { const char * tb_v2238 = "        while (tb_gsz[c] < i * 8) c++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2238; }
    { const char * tb_v2239 = "        tb_gcls[i] = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2239; }
    { const char * tb_v2240 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2240; }
    { const char * tb_v2241 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2241; }
    { const char * tb_v2242 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
    { const char * tb_v2244 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "    tb_gpage **l2 = tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
    { const char * tb_v2246 = "    return l2 ? l2[(a >> TB_GSH) & 0xFFFF] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2246; }
    { const char * tb_v2247 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2247; }
    { const char * tb_v2248 = "TB_API void tb_gmap_put(uintptr_t a, tb_gpage *pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2248; }
    { const char * tb_v2249 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2249; }
    { const char * tb_v2250 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2250; }
    { const char * tb_v2251 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v2251; }
    { const char * tb_v2252 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2252; }
    { const char * tb_v2253 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2253; }
    { const char * tb_v2254 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2254; }
    { const char * tb_v2255 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
    { const char * tb_v2256 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2256; }
    { const char * tb_v2257 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v2257; }
    { const char * tb_v2258 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "    if ((uintptr_t)pg->start + size > tb_ghi) tb_ghi = (uintptr_t)pg->start + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
    { const char * tb_v2260 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2260; }
    { const char * tb_v2261 = "TB_API void tb_gmap_remove(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2261; }
    { const char * tb_v2262 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2262; }
    { const char * tb_v2263 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2263; }
    { const char * tb_v2264 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v2264; }
    { const char * tb_v2265 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2265; }
    { const char * tb_v2266 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v2266; }
    { const char * tb_v2267 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v2267; }
    { const char * tb_v2268 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2268; }
    { const char * tb_v2269 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2269; }
    { const char * tb_v2270 = "    if (!m) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2270; }
    { const char * tb_v2271 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v2271; }
    { const char * tb_v2272 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2272; }
    { const char * tb_v2273 = "#define munmap(p, n) (VirtualFree((p), 0, MEM_RELEASE) ? 0 : -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2273; }
    { const char * tb_v2274 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2274; }
    { const char * tb_v2275 = "#include <sys/mman.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2275; }
    { const char * tb_v2276 = "#ifdef __linux__\n"; *(const char * *)tb_grow(v_lines) = tb_v2276; }
    { const char * tb_v2277 = "#ifndef MREMAP_MAYMOVE\n"; *(const char * *)tb_grow(v_lines) = tb_v2277; }
    { const char * tb_v2278 = "#define MREMAP_MAYMOVE 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2278; }
    { const char * tb_v2279 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2279; }
    { const char * tb_v2280 = "#ifndef MREMAP_FIXED\n"; *(const char * *)tb_grow(v_lines) = tb_v2280; }
    { const char * tb_v2281 = "#define MREMAP_FIXED 2\n"; *(const char * *)tb_grow(v_lines) = tb_v2281; }
    { const char * tb_v2282 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2282; }
    { const char * tb_v2283 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v2283; }
    { const char * tb_v2284 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2284; }
    { const char * tb_v2285 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2285; }
    { const char * tb_v2286 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v2286; }
    { const char * tb_v2287 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2287; }
    { const char * tb_v2288 = "    if (m == MAP_FAILED) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2288; }
    { const char * tb_v2289 = "    uintptr_t a = ((uintptr_t)m + TB_GPG - 1) & ~(uintptr_t)(TB_GPG - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2289; }
    { const char * tb_v2290 = "    if (a > (uintptr_t)m) munmap(m, a - (uintptr_t)m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2290; }
    { const char * tb_v2291 = "    size_t tail = (uintptr_t)m + tot - (a + (size_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2291; }
    { const char * tb_v2292 = "    if (tail) munmap((char *)a + size, tail);\n"; *(const char * *)tb_grow(v_lines) = tb_v2292; }
    { const char * tb_v2293 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v2293; }
    { const char * tb_v2294 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2294; }
