    { const char * tb_v3685 = "    tb_export_list(d->vals, vtext);\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
