    { const char * tb_v3755 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
