    { const char * tb_v3791 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
    { const char * tb_v3792 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3792; }
    { const char * tb_v3793 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v3793; }
    { const char * tb_v3794 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3794; }
    { const char * tb_v3795 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
