    { const char * tb_v3807 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
