    { const char * tb_v3829 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
    { const char * tb_v3836 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3836; }
    { const char * tb_v3837 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v3837; }
    { const char * tb_v3838 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
    { const char * tb_v3842 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3842; }
