    { const char * tb_v3852 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v3852; }
    { const char * tb_v3853 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
