    { const char * tb_v3857 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
    { const char * tb_v3862 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3862; }
    { const char * tb_v3863 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3863; }
    { const char * tb_v3864 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3864; }
    { const char * tb_v3865 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3865; }
    { const char * tb_v3866 = "        if (o < (unsigned long long)d->npos) { __builtin_prefetch(&d->pos[o]); return o; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3866; }
    { const char * tb_v3867 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3867; }
