    { const char * tb_v3885 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3885; }
    { const char * tb_v3886 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3886; }
    { const char * tb_v3887 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3887; }
