    { const char * tb_v3898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3898; }
    { const char * tb_v3899 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3899; }
    { const char * tb_v3900 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3900; }
    { const char * tb_v3901 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
    { const char * tb_v3905 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3905; }
    { const char * tb_v3906 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3906; }
    { const char * tb_v3907 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3907; }
    { const char * tb_v3908 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3908; }
    { const char * tb_v3909 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3909; }
    { const char * tb_v3910 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3910; }
    { const char * tb_v3911 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3911; }
    { const char * tb_v3912 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3912; }
    { const char * tb_v3913 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3913; }
    { const char * tb_v3914 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3914; }
    { const char * tb_v3915 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3915; }
    { const char * tb_v3916 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v3916; }
    { const char * tb_v3917 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3917; }
    { const char * tb_v3918 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3918; }
    { const char * tb_v3919 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3919; }
    { const char * tb_v3920 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3920; }
    { const char * tb_v3921 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3921; }
    { const char * tb_v3922 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3922; }
    { const char * tb_v3923 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3923; }
    { const char * tb_v3924 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3924; }
    { const char * tb_v3925 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3925; }
    { const char * tb_v3926 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3926; }
    { const char * tb_v3927 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3927; }
    { const char * tb_v3928 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3928; }
    { const char * tb_v3929 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3929; }
    { const char * tb_v3930 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3930; }
    { const char * tb_v3931 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3931; }
    { const char * tb_v3932 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3932; }
    { const char * tb_v3933 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3933; }
    { const char * tb_v3934 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3934; }
    { const char * tb_v3935 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3935; }
    { const char * tb_v3936 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3936; }
    { const char * tb_v3937 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3937; }
    { const char * tb_v3938 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3938; }
    { const char * tb_v3939 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3939; }
    { const char * tb_v3940 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3940; }
    { const char * tb_v3941 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3941; }
    { const char * tb_v3942 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3942; }
    { const char * tb_v3943 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3943; }
    { const char * tb_v3944 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3944; }
    { const char * tb_v3945 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3945; }
    { const char * tb_v3946 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3946; }
    { const char * tb_v3947 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3947; }
    { const char * tb_v3948 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3948; }
    { const char * tb_v3949 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3949; }
    { const char * tb_v3950 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3950; }
    { const char * tb_v3951 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3951; }
    { const char * tb_v3952 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3952; }
    { const char * tb_v3953 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3953; }
    { const char * tb_v3954 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3954; }
    { const char * tb_v3955 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3955; }
    { const char * tb_v3956 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3956; }
    { const char * tb_v3957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3957; }
    { const char * tb_v3958 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3958; }
    { const char * tb_v3959 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3959; }
    { const char * tb_v3960 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3960; }
    { const char * tb_v3961 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3961; }
    { const char * tb_v3962 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3962; }
    { const char * tb_v3963 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3963; }
    { const char * tb_v3964 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3964; }
    { const char * tb_v3965 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3965; }
    { const char * tb_v3966 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3966; }
    { const char * tb_v3967 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3967; }
    { const char * tb_v3968 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3968; }
    { const char * tb_v3969 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3969; }
    { const char * tb_v3970 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3970; }
    { const char * tb_v3971 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3971; }
    { const char * tb_v3972 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3972; }
    { const char * tb_v3973 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3973; }
    { const char * tb_v3974 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3974; }
    { const char * tb_v3975 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3975; }
    { const char * tb_v3976 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3976; }
    { const char * tb_v3977 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3977; }
    { const char * tb_v3978 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3978; }
    { const char * tb_v3979 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3979; }
    { const char * tb_v3980 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3980; }
    { const char * tb_v3981 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3981; }
    { const char * tb_v3982 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3982; }
    { const char * tb_v3983 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3983; }
    { const char * tb_v3984 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3984; }
    { const char * tb_v3985 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3985; }
    { const char * tb_v3986 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3986; }
    { const char * tb_v3987 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3987; }
    { const char * tb_v3988 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3988; }
    { const char * tb_v3989 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3989; }
    { const char * tb_v3990 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3990; }
    { const char * tb_v3991 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3991; }
    { const char * tb_v3992 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3992; }
    { const char * tb_v3993 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3993; }
    { const char * tb_v3994 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3994; }
    { const char * tb_v3995 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3995; }
    { const char * tb_v3996 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3996; }
    { const char * tb_v3997 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3997; }
    { const char * tb_v3998 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3998; }
    { const char * tb_v3999 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3999; }
    { const char * tb_v4000 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v4000; }
    { const char * tb_v4001 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4001; }
    { const char * tb_v4002 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4002; }
    { const char * tb_v4003 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4003; }
    { const char * tb_v4004 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4004; }
    { const char * tb_v4005 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4005; }
    { const char * tb_v4006 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4006; }
    { const char * tb_v4007 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v4007; }
    { const char * tb_v4008 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v4008; }
    { const char * tb_v4009 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4009; }
    { const char * tb_v4010 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4010; }
    { const char * tb_v4011 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v4011; }
    { const char * tb_v4012 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4012; }
    { const char * tb_v4013 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v4013; }
    { const char * tb_v4014 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4014; }
    { const char * tb_v4015 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4015; }
    { const char * tb_v4016 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v4016; }
    { const char * tb_v4017 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4017; }
    { const char * tb_v4018 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4018; }
    { const char * tb_v4019 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4019; }
    { const char * tb_v4020 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4020; }
    { const char * tb_v4021 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v4021; }
    { const char * tb_v4022 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4022; }
    { const char * tb_v4023 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v4023; }
    { const char * tb_v4024 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4024; }
    { const char * tb_v4025 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4025; }
    { const char * tb_v4026 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4026; }
    { const char * tb_v4027 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4027; }
    { const char * tb_v4028 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4028; }
    { const char * tb_v4029 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v4029; }
    { const char * tb_v4030 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4030; }
    { const char * tb_v4031 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v4031; }
    { const char * tb_v4032 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4032; }
    { const char * tb_v4033 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v4033; }
    { const char * tb_v4034 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4034; }
    { const char * tb_v4035 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4035; }
    { const char * tb_v4036 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v4036; }
    { const char * tb_v4037 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4037; }
    { const char * tb_v4038 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4038; }
    { const char * tb_v4039 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4039; }
    { const char * tb_v4040 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4040; }
    { const char * tb_v4041 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4041; }
    { const char * tb_v4042 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4042; }
    { const char * tb_v4043 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4043; }
    { const char * tb_v4044 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4044; }
    { const char * tb_v4045 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4045; }
    { const char * tb_v4046 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4046; }
    { const char * tb_v4047 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4047; }
    { const char * tb_v4048 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4048; }
    { const char * tb_v4049 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4049; }
    { const char * tb_v4050 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4050; }
    { const char * tb_v4051 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4051; }
