    { const char * tb_v4211 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v4211; }
    { const char * tb_v4212 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4212; }
    { const char * tb_v4213 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4213; }
