    { const char * tb_v4232 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4232; }
    { const char * tb_v4233 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4233; }
    { const char * tb_v4234 = "    tb_mem_soft(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4234; }
    { const char * tb_v4235 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4235; }
    { const char * tb_v4236 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4236; }
    { const char * tb_v4237 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4237; }
