    { const char * tb_v4428 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4428; }
    { const char * tb_v4429 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4429; }
