    { const char * tb_v4823 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4823; }
    { const char * tb_v4824 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4824; }
    { const char * tb_v4825 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4825; }
    { const char * tb_v4826 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4826; }
    { const char * tb_v4827 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v4827; }
    { const char * tb_v4828 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4828; }
    { const char * tb_v4829 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4829; }
    { const char * tb_v4830 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4830; }
    { const char * tb_v4831 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4831; }
    { const char * tb_v4832 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4832; }
    { const char * tb_v4833 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4833; }
    { const char * tb_v4834 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4834; }
    { const char * tb_v4835 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4835; }
    { const char * tb_v4836 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4836; }
    { const char * tb_v4837 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4837; }
    { const char * tb_v4838 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4838; }
    { const char * tb_v4839 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v4839; }
    { const char * tb_v4840 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v4840; }
    { const char * tb_v4841 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4841; }
