    { const char * tb_v4843 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4843; }
    { const char * tb_v4844 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4844; }
    { const char * tb_v4845 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4845; }
    { const char * tb_v4846 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4846; }
    { const char * tb_v4847 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v4847; }
