    { const char * tb_v4849 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4849; }
    { const char * tb_v4850 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4850; }
    { const char * tb_v4851 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4851; }
    { const char * tb_v4852 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4852; }
    { const char * tb_v4853 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4853; }
    { const char * tb_v4854 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4854; }
    { const char * tb_v4855 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4855; }
    { const char * tb_v4856 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4856; }
