    { const char * tb_v4889 = "                for (int i = 256; i < 280; i++) lens[i] = 7;\n"; *(const char * *)tb_grow(v_lines) = tb_v4889; }
    { const char * tb_v4890 = "                for (int i = 280; i < 288; i++) lens[i] = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4890; }
    { const char * tb_v4891 = "                for (int i = 0; i < 30; i++) lens[288 + i] = 5;\n"; *(const char * *)tb_grow(v_lines) = tb_v4891; }
    { const char * tb_v4892 = "            } else {           // свои коды в начале блока\n"; *(const char * *)tb_grow(v_lines) = tb_v4892; }
    { const char * tb_v4893 = "                nl = (int)tb_zbits(z, 5) + 257; nd = (int)tb_zbits(z, 5) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4893; }
    { const char * tb_v4894 = "                int nc = (int)tb_zbits(z, 4) + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4894; }
    { const char * tb_v4895 = "                unsigned char cl[19] = { 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4895; }
    { const char * tb_v4896 = "                for (int i = 0; i < nc; i++) cl[order[i]] = (unsigned char)tb_zbits(z, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v4896; }
    { const char * tb_v4897 = "                tb_huff ch; tb_hbuild(&ch, cl, 19);\n"; *(const char * *)tb_grow(v_lines) = tb_v4897; }
    { const char * tb_v4898 = "                int i = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4898; }
    { const char * tb_v4899 = "                while (i < nl + nd && !z->err) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4899; }
    { const char * tb_v4900 = "                    int s = tb_hdec(z, &ch), rep = 0, val = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4900; }
