    { const char * tb_v5471 = "// картинка из байтов в памяти (PNG, JPEG, BMP, GIF) → номер картинки; -1 и tb_err — не вышло\n"; *(const char * *)tb_grow(v_lines) = tb_v5471; }
    { const char * tb_v5472 = "TB_API long long tb_image_add(const unsigned char *d, size_t sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5472; }
    { const char * tb_v5473 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5473; }
