    { const char * tb_v5488 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5488; }
    { const char * tb_v5489 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5489; }
    { const char * tb_v5490 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5490; }
    { const char * tb_v5491 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5491; }
    { const char * tb_v5492 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5492; }
    { const char * tb_v5493 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5493; }
    { const char * tb_v5494 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5494; }
    { const char * tb_v5495 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
