    { const char * tb_v5500 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "// image_from_mem(адрес, байт): картинка из памяти (файл прочитан со своего диска, пришёл по сети ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "TB_API long long tb_image_from_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
    { const char * tb_v5503 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v5503; }
    { const char * tb_v5504 = "    if (!a || n <= 0) { tb_err = \"пустая память\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5504; }
    { const char * tb_v5505 = "    return tb_image_add((const unsigned char *)(uintptr_t)a, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5505; }
