    { const char * tb_v6062 = "TB_API void *tb_gpu_sh_vbuf(void *old, const float *v, long long nfloats);\n"; *(const char * *)tb_grow(v_lines) = tb_v6062; }
    { const char * tb_v6063 = "TB_API void tb_gpu_sh_add(void *vb, int cs, int ps, long long nverts, int nowrite);   // nowrite: глубину не писать (прозрачная сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v6063; }
    { const char * tb_v6064 = "TB_API int tb_gpu_scr_ready(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v6064; }
    { const char * tb_v6065 = "// ---- тени для gpu func: карта солнца (1024 × 1024) и кубы ламп (6 × 256 × 256, до 4 ламп) по 16 бит —\n"; *(const char * *)tb_grow(v_lines) = tb_v6065; }
    { const char * tb_v6066 = "// две глубины в слове; у каждого набора видеокарты свои (прошлые кадры ещё рисуются). Начало — число 207 записи\n"; *(const char * *)tb_grow(v_lines) = tb_v6066; }
    { const char * tb_v6067 = "enum { TB_LSM_N = 256, TB_LSM_MAX = 4 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6067; }
    { const char * tb_v6068 = "#define TB_SHM_SLOT ((size_t)1024 * 1024 + (size_t)TB_LSM_MAX * 6 * TB_LSM_N * TB_LSM_N)\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "TB_API uint32_t *tb_shm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
    { const char * tb_v6070 = "TB_API int tb_lshadow[8];             // light_shadow: лампа даёт тени\n"; *(const char * *)tb_grow(v_lines) = tb_v6070; }
    { const char * tb_v6071 = "TB_API int tb_lsm_of[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };   // куб лампы в картах этой сцены\n"; *(const char * *)tb_grow(v_lines) = tb_v6071; }
    { const char * tb_v6072 = "TB_API int tb_shm_sun = 0;            // в картах этой сцены есть солнце\n"; *(const char * *)tb_grow(v_lines) = tb_v6072; }
    { const char * tb_v6073 = "TB_API long long tb_shm_batch = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "TB_API uint32_t *tb_gpu_shm(void);    // своя у каждой системы: память карт, которую видит видеокарта (0 — нет)\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "TB_API void tb_gpu_scr_add(int ps);\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "    if (tb_sh_frame) { tb_sh_frame = 0; tb_gpu_shskip++; return; }   // свои шейдеры: дробные числа, точка в точку не сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
    { const char * tb_v6085 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6085; }
    { const char * tb_v6086 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6086; }
    { const char * tb_v6087 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6087; }
    { const char * tb_v6088 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6088; }
    { const char * tb_v6089 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6089; }
    { const char * tb_v6090 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v6090; }
    { const char * tb_v6091 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v6091; }
    { const char * tb_v6092 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v6092; }
    { const char * tb_v6093 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6093; }
    { const char * tb_v6094 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6094; }
    { const char * tb_v6095 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6095; }
    { const char * tb_v6096 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6096; }
    { const char * tb_v6097 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v6097; }
    { const char * tb_v6098 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6098; }
    { const char * tb_v6099 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v6099; }
    { const char * tb_v6100 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6100; }
    { const char * tb_v6101 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v6101; }
    { const char * tb_v6102 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6102; }
    { const char * tb_v6103 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6103; }
    { const char * tb_v6104 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6104; }
    { const char * tb_v6105 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6105; }
    { const char * tb_v6106 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6106; }
    { const char * tb_v6107 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6107; }
    { const char * tb_v6108 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6108; }
    { const char * tb_v6109 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6109; }
    { const char * tb_v6110 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6110; }
    { const char * tb_v6111 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6111; }
    { const char * tb_v6112 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6112; }
    { const char * tb_v6113 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6113; }
    { const char * tb_v6114 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6114; }
    { const char * tb_v6115 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6115; }
    { const char * tb_v6116 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6116; }
    { const char * tb_v6117 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6117; }
    { const char * tb_v6118 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6118; }
    { const char * tb_v6119 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6119; }
    { const char * tb_v6120 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6120; }
    { const char * tb_v6121 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6121; }
    { const char * tb_v6122 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6122; }
    { const char * tb_v6123 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6123; }
    { const char * tb_v6124 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6124; }
    { const char * tb_v6125 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6125; }
    { const char * tb_v6126 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v6126; }
    { const char * tb_v6127 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6127; }
    { const char * tb_v6128 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6128; }
    { const char * tb_v6129 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v6129; }
    { const char * tb_v6130 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6130; }
    { const char * tb_v6131 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6131; }
    { const char * tb_v6132 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6132; }
    { const char * tb_v6133 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v6133; }
    { const char * tb_v6134 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6134; }
    { const char * tb_v6135 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6135; }
    { const char * tb_v6136 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6136; }
    { const char * tb_v6137 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6137; }
    { const char * tb_v6138 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6138; }
    { const char * tb_v6139 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6139; }
    { const char * tb_v6140 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6140; }
    { const char * tb_v6141 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6141; }
    { const char * tb_v6142 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6142; }
    { const char * tb_v6143 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6143; }
    { const char * tb_v6144 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6144; }
    { const char * tb_v6145 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v6145; }
    { const char * tb_v6146 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6146; }
    { const char * tb_v6147 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6147; }
    { const char * tb_v6148 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6148; }
    { const char * tb_v6149 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6149; }
    { const char * tb_v6150 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6150; }
    { const char * tb_v6151 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6151; }
    { const char * tb_v6152 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6152; }
    { const char * tb_v6153 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v6153; }
    { const char * tb_v6154 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v6154; }
    { const char * tb_v6155 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6155; }
    { const char * tb_v6156 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 1u);\n"; *(const char * *)tb_grow(v_lines) = tb_v6156; }
    { const char * tb_v6157 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6157; }
    { const char * tb_v6158 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v6158; }
    { const char * tb_v6159 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6159; }
    { const char * tb_v6160 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6160; }
    { const char * tb_v6161 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v6161; }
    { const char * tb_v6162 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v6162; }
    { const char * tb_v6163 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6163; }
    { const char * tb_v6164 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v6164; }
    { const char * tb_v6165 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6165; }
    { const char * tb_v6166 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v6166; }
    { const char * tb_v6167 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v6167; }
    { const char * tb_v6168 = "// 3 — «новый» треугольник, 4 — он же прозрачный (глубину не пишет)\n"; *(const char * *)tb_grow(v_lines) = tb_v6168; }
    { const char * tb_v6169 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 28) & 1u ? 3 + (int)((m >> 27) & 1u) : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6169; }
    { const char * tb_v6170 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6170; }
    { const char * tb_v6171 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6171; }
    { const char * tb_v6172 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v6172; }
    { const char * tb_v6173 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v6173; }
    { const char * tb_v6174 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v6174; }
    { const char * tb_v6175 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v6175; }
    { const char * tb_v6176 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v6176; }
    { const char * tb_v6177 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6177; }
    { const char * tb_v6178 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6178; }
    { const char * tb_v6179 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6179; }
    { const char * tb_v6180 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6180; }
    { const char * tb_v6181 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6181; }
    { const char * tb_v6182 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6182; }
    { const char * tb_v6183 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6183; }
    { const char * tb_v6184 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6184; }
    { const char * tb_v6185 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6185; }
    { const char * tb_v6186 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6186; }
    { const char * tb_v6187 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6187; }
    { const char * tb_v6188 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6188; }
    { const char * tb_v6189 = "#if !defined(__APPLE__) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v6189; }
    { const char * tb_v6190 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v6190; }
