    { const char * tb_v6192 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6192; }
    { const char * tb_v6193 = "// ---------- Vulkan (Linux и Windows) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6193; }
    { const char * tb_v6194 = "// Свои описания Vulkan (только то, что нужно): программе не нужны заголовки Vulkan,\n"; *(const char * *)tb_grow(v_lines) = tb_v6194; }
    { const char * tb_v6195 = "// а сама библиотека Vulkan грузится при запуске (dlopen) — нет её, рисуем на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v6195; }
