    { const char * tb_v9113 = "// Мышь PS/2 (прерывание 12), клавиатура — та же, что для read_key.\n"; *(const char * *)tb_grow(v_lines) = tb_v9113; }
    { const char * tb_v9114 = "TB_API volatile uint32_t *tb_lfb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9114; }
