    { const char * tb_v9123 = "        for (int dev = 0; dev < 32; dev++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9123; }
    { const char * tb_v9124 = "            unsigned id = tb_pci_r(bus, dev, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9124; }
    { const char * tb_v9125 = "            if (id == 0x11111234u || id == 0xBEEF80EEu) return tb_pci_r(bus, dev, 0, 0x10) & ~0xFu;\n"; *(const char * *)tb_grow(v_lines) = tb_v9125; }
    { const char * tb_v9126 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9126; }
