    { const char * tb_v9140 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v9140; }
    { const char * tb_v9141 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9141; }
    { const char * tb_v9142 = "TB_API int tb_sc_key(unsigned char sc, int ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
    { const char * tb_v9143 = "    if (ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9143; }
