    { const char * tb_v9146 = "        case 0x53: return TB_K_DEL; case 0x47: return TB_K_HOME; case 0x4F: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v9146; }
    { const char * tb_v9147 = "        case 0x49: return TB_K_PGUP; case 0x51: return TB_K_PGDN; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v9147; }
    { const char * tb_v9148 = "        case 0x1C: return TB_K_ENTER;\n"; *(const char * *)tb_grow(v_lines) = tb_v9148; }
