    { const char * tb_v9151 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9151; }
    { const char * tb_v9152 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9152; }
    { const char * tb_v9153 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v9153; }
    { const char * tb_v9154 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v9154; }
    { const char * tb_v9155 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v9155; }
    { const char * tb_v9156 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9156; }
    { const char * tb_v9157 = "    if (sc >= 0x3B && sc <= 0x44) return TB_K_F1 + (sc - 0x3B);\n"; *(const char * *)tb_grow(v_lines) = tb_v9157; }
    { const char * tb_v9158 = "    if (sc < 58) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9158; }
