    { const char * tb_v9162 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9162; }
    { const char * tb_v9163 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9163; }
    { const char * tb_v9164 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9164; }
    { const char * tb_v9165 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9165; }
    { const char * tb_v9166 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9166; }
    { const char * tb_v9167 = "    int up = sc & 0x80, ext = tb_kext;\n"; *(const char * *)tb_grow(v_lines) = tb_v9167; }
    { const char * tb_v9168 = "    tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9168; }
    { const char * tb_v9169 = "    sc &= 0x7F;\n"; *(const char * *)tb_grow(v_lines) = tb_v9169; }
    { const char * tb_v9170 = "    int k = tb_sc_key(sc, ext);\n"; *(const char * *)tb_grow(v_lines) = tb_v9170; }
    { const char * tb_v9171 = "    if (k) { tb_keys[k] = !up; if (!up) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9171; }
    { const char * tb_v9172 = "    if (!up && !ext && sc < 58 && !tb_keys[TB_K_CTRL]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9172; }
    { const char * tb_v9173 = "        char ch = tb_kmap[tb_keys[TB_K_SHIFT] ? 1 : 0][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v9173; }
    { const char * tb_v9174 = "        if ((unsigned char)ch >= 32) tb_type_cp((unsigned char)ch);\n"; *(const char * *)tb_grow(v_lines) = tb_v9174; }
