    { const char * tb_v9176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9176; }
    { const char * tb_v9177 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v9177; }
    { const char * tb_v9178 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v9178; }
    { const char * tb_v9179 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v9179; }
    { const char * tb_v9180 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v9180; }
    { const char * tb_v9181 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9181; }
    { const char * tb_v9182 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v9182; }
    { const char * tb_v9183 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9183; }
    { const char * tb_v9184 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9184; }
    { const char * tb_v9185 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9185; }
    { const char * tb_v9186 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9186; }
