    { const char * tb_v9189 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9189; }
    { const char * tb_v9190 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v9190; }
    { const char * tb_v9191 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v9191; }
    { const char * tb_v9192 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9192; }
    { const char * tb_v9193 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9193; }
    { const char * tb_v9194 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v9194; }
    { const char * tb_v9195 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9195; }
    { const char * tb_v9196 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9196; }
    { const char * tb_v9197 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9197; }
    { const char * tb_v9198 = "TB_API void tb_vmm_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9198; }
