    { const char * tb_v10730 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10730; }
    { const char * tb_v10731 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v10731; }
    { const char * tb_v10732 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v10732; }
    { const char * tb_v10733 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v10733; }
    { const char * tb_v10734 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v10734; }
    { const char * tb_v10735 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v10735; }
    { const char * tb_v10736 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v10736; }
    { const char * tb_v10737 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10737; }
    { const char * tb_v10738 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10738; }
    { const char * tb_v10739 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10739; }
    { const char * tb_v10740 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v10740; }
    { const char * tb_v10741 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v10741; }
    { const char * tb_v10742 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10742; }
    { const char * tb_v10743 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10743; }
    { const char * tb_v10744 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v10744; }
    { const char * tb_v10745 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v10745; }
    { const char * tb_v10746 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v10746; }
    { const char * tb_v10747 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v10747; }
