    { const char * tb_v10860 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v10860; }
    { const char * tb_v10861 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v10861; }
    { const char * tb_v10862 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v10862; }
    { const char * tb_v10863 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v10863; }
    { const char * tb_v10864 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v10864; }
    { const char * tb_v10865 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10865; }
    { const char * tb_v10866 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10866; }
    { const char * tb_v10867 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10867; }
    { const char * tb_v10868 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10868; }
    { const char * tb_v10869 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10869; }
    { const char * tb_v10870 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v10870; }
    { const char * tb_v10871 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10871; }
    { const char * tb_v10872 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v10872; }
    { const char * tb_v10873 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v10873; }
    { const char * tb_v10874 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v10874; }
    { const char * tb_v10875 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10875; }
    { const char * tb_v10876 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10876; }
    { const char * tb_v10877 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v10877; }
    { const char * tb_v10878 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v10878; }
    { const char * tb_v10879 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v10879; }
    { const char * tb_v10880 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10880; }
    { const char * tb_v10881 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10881; }
    { const char * tb_v10882 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10882; }
    { const char * tb_v10883 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10883; }
    { const char * tb_v10884 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10884; }
    { const char * tb_v10885 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v10885; }
    { const char * tb_v10886 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10886; }
    { const char * tb_v10887 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10887; }
    { const char * tb_v10888 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10888; }
    { const char * tb_v10889 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10889; }
    { const char * tb_v10890 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10890; }
    { const char * tb_v10891 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10891; }
    { const char * tb_v10892 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10892; }
    { const char * tb_v10893 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10893; }
    { const char * tb_v10894 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10894; }
    { const char * tb_v10895 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v10895; }
    { const char * tb_v10896 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10896; }
    { const char * tb_v10897 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10897; }
    { const char * tb_v10898 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10898; }
    { const char * tb_v10899 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10899; }
    { const char * tb_v10900 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10900; }
    { const char * tb_v10901 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10901; }
    { const char * tb_v10902 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v10902; }
    { const char * tb_v10903 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10903; }
    { const char * tb_v10904 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10904; }
    { const char * tb_v10905 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v10905; }
    { const char * tb_v10906 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10906; }
