    { const char * tb_v10920 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v10920; }
    { const char * tb_v10921 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v10921; }
    { const char * tb_v10922 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v10922; }
    { const char * tb_v10923 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v10923; }
    { const char * tb_v10924 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10924; }
