    { const char * tb_v10934 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v10934; }
    { const char * tb_v10935 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v10935; }
    { const char * tb_v10936 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v10936; }
    { const char * tb_v10937 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v10937; }
    { const char * tb_v10938 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v10938; }
    { const char * tb_v10939 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10939; }
    { const char * tb_v10940 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v10940; }
