    { const char * tb_v10948 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v10948; }
