    { const char * tb_v10952 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v10952; }
    { const char * tb_v10953 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10953; }
