    { const char * tb_v10955 = "// сделать окно i текущим: 3D, которое ждало, дорисовывается в прежнее окно\n"; *(const char * *)tb_grow(v_lines) = tb_v10955; }
    { const char * tb_v10956 = "TB_API void tb_wswitch(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10956; }
    { const char * tb_v10957 = "    if (i == tb_wcur || i < 0 || i >= tb_wn || !tb_wins[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10957; }
