    { const char * tb_v10963 = "TB_API void tb_wmark_closed(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10963; }
    { const char * tb_v10964 = "    if (i == tb_wcur) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10964; }
    { const char * tb_v10965 = "    else if (i >= 0 && i < tb_wn) tb_wins[i].gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10965; }
    { const char * tb_v10966 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10966; }
    { const char * tb_v10967 = "TB_API int tb_gfx_open2(const char *title);\n"; *(const char * *)tb_grow(v_lines) = tb_v10967; }
    { const char * tb_v10968 = "TB_API void tb_gfx_show(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v10968; }
    { const char * tb_v10969 = "TB_API void tb_gfx_close2(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v10969; }
    { const char * tb_v10970 = "TB_API void tb_gfx_poll(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v10970; }
    { const char * tb_v10971 = "TB_API long long tb_window_new(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10971; }
    { const char * tb_v10972 = "    if (tb_wn == 0) { tb_err = \"сначала открой главное окно: window_open\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10972; }
    { const char * tb_v10973 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10973; }
    { const char * tb_v10974 = "    int i = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10974; }
