    { const char * tb_v10979 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v10979; }
    { const char * tb_v10980 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v10980; }
    { const char * tb_v10981 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10981; }
    { const char * tb_v10982 = "    int was = tb_wcur;\n"; *(const char * *)tb_grow(v_lines) = tb_v10982; }
    { const char * tb_v10983 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10983; }
    { const char * tb_v10984 = "    tb_wsave(&tb_wins[was]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10984; }
    { const char * tb_v10985 = "    tb_wslot *s = &tb_wins[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10985; }
    { const char * tb_v10986 = "    memset(s, 0, sizeof *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v10986; }
    { const char * tb_v10987 = "    s->gw = (int)w; s->gh = (int)h; s->zclr = s->gzclr = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10987; }
    { const char * tb_v10988 = "    s->px = calloc((size_t)w * h, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10988; }
    { const char * tb_v10989 = "    tb_wload(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v10989; }
    { const char * tb_v10990 = "    int ok = tb_px && tb_gfx_open2(title);\n"; *(const char * *)tb_grow(v_lines) = tb_v10990; }
    { const char * tb_v10991 = "    if (ok) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10991; }
    { const char * tb_v10992 = "        s->used = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10992; }
