    { const char * tb_v10994 = "        if (i >= tb_wn) tb_wn = i + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10994; }
    { const char * tb_v10995 = "        tb_wsave(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v10995; }
    { const char * tb_v10996 = "    } else free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v10996; }
    { const char * tb_v10997 = "    tb_wload(&tb_wins[was]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10997; }
    { const char * tb_v10998 = "    if (!ok) { tb_err = \"не могу открыть окно\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10998; }
    { const char * tb_v10999 = "    return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v10999; }
