    { const char * tb_v11002 = "    if (n < 0 || n >= tb_wn || !tb_wins[n].used) { fprintf(stderr, \"ошибка: window_use(%lld): нет такого окна\\n\", n); exit(1); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11002; }
