    { const char * tb_v11005 = "// закрыть окно: оно пропадает с экрана, window_shown() — false. window_close(0) — как закрыть главное окно\n"; *(const char * *)tb_grow(v_lines) = tb_v11005; }
    { const char * tb_v11006 = "TB_API void tb_window_close(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11006; }
    { const char * tb_v11007 = "    if (n == 0) { tb_wmark_closed(0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11007; }
    { const char * tb_v11008 = "    if (n < 0 || n >= tb_wn || !tb_wins[n].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11008; }
