    { const char * tb_v11026 = "// полный экран (true) и снова окно (false). Размер кадра меняется: смотри window_w(), window_h()\n"; *(const char * *)tb_grow(v_lines) = tb_v11026; }
    { const char * tb_v11027 = "TB_API void tb_window_fullscreen(int on) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11027; }
    { const char * tb_v11028 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11028; }
