    { const char * tb_v11032 = "// захват мыши для игр от первого лица: курсора не видно, он не упирается в край, поворот — mouse_dx/mouse_dy\n"; *(const char * *)tb_grow(v_lines) = tb_v11032; }
    { const char * tb_v11033 = "TB_API void tb_mouse_lock(int on) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11033; }
    { const char * tb_v11034 = "    if (!tb_px || (on != 0) == tb_mlock) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11034; }
