    { const char * tb_v11125 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v11125; }
    { const char * tb_v11126 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v11126; }
    { const char * tb_v11127 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11127; }
    { const char * tb_v11128 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11128; }
    { const char * tb_v11129 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11129; }
    { const char * tb_v11130 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v11130; }
    { const char * tb_v11131 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11131; }
