    { const char * tb_v11140 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11140; }
    { const char * tb_v11141 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11141; }
    { const char * tb_v11142 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v11142; }
