    { const char * tb_v11146 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11146; }
    { const char * tb_v11147 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11147; }
    { const char * tb_v11148 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v11148; }
    { const char * tb_v11149 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v11149; }
    { const char * tb_v11150 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v11150; }
    { const char * tb_v11151 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v11151; }
    { const char * tb_v11152 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11152; }
    { const char * tb_v11153 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11153; }
    { const char * tb_v11154 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11154; }
    { const char * tb_v11155 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11155; }
