    { const char * tb_v11157 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11157; }
    { const char * tb_v11158 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11158; }
    { const char * tb_v11159 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11159; }
    { const char * tb_v11160 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11160; }
    { const char * tb_v11161 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11161; }
    { const char * tb_v11162 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v11162; }
    { const char * tb_v11163 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v11163; }
    { const char * tb_v11164 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11164; }
    { const char * tb_v11165 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v11165; }
    { const char * tb_v11166 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11166; }
    { const char * tb_v11167 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v11167; }
    { const char * tb_v11168 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v11168; }
    { const char * tb_v11169 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v11169; }
    { const char * tb_v11170 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v11170; }
    { const char * tb_v11171 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11171; }
    { const char * tb_v11172 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11172; }
    { const char * tb_v11173 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v11173; }
    { const char * tb_v11174 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11174; }
    { const char * tb_v11175 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v11175; }
    { const char * tb_v11176 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11176; }
