    { const char * tb_v11231 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v11231; }
