    { const char * tb_v11243 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v11243; }
    { const char * tb_v11244 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11244; }
