    { const char * tb_v11268 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11268; }
    { const char * tb_v11269 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v11269; }
    { const char * tb_v11270 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v11270; }
