    { const char * tb_v11282 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11282; }
    { const char * tb_v11283 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v11283; }
    { const char * tb_v11284 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v11284; }
    { const char * tb_v11285 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11285; }
    { const char * tb_v11286 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v11286; }
    { const char * tb_v11287 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11287; }
    { const char * tb_v11288 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v11288; }
    { const char * tb_v11289 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11289; }
    { const char * tb_v11290 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v11290; }
    { const char * tb_v11291 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v11291; }
    { const char * tb_v11292 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11292; }
    { const char * tb_v11293 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11293; }
    { const char * tb_v11294 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v11294; }
    { const char * tb_v11295 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v11295; }
    { const char * tb_v11296 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11296; }
    { const char * tb_v11297 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v11297; }
    { const char * tb_v11298 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v11298; }
    { const char * tb_v11299 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v11299; }
    { const char * tb_v11300 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11300; }
    { const char * tb_v11301 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11301; }
    { const char * tb_v11302 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v11302; }
    { const char * tb_v11303 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v11303; }
    { const char * tb_v11304 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11304; }
    { const char * tb_v11305 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11305; }
    { const char * tb_v11306 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11306; }
    { const char * tb_v11307 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v11307; }
