    { const char * tb_v11573 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v11573; }
    { const char * tb_v11574 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11574; }
    { const char * tb_v11575 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v11575; }
    { const char * tb_v11576 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v11576; }
    { const char * tb_v11577 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v11577; }
    { const char * tb_v11578 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11578; }
    { const char * tb_v11579 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11579; }
    { const char * tb_v11580 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v11580; }
    { const char * tb_v11581 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v11581; }
    { const char * tb_v11582 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v11582; }
    { const char * tb_v11583 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v11583; }
    { const char * tb_v11584 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v11584; }
    { const char * tb_v11585 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v11585; }
    { const char * tb_v11586 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v11586; }
    { const char * tb_v11587 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11587; }
    { const char * tb_v11588 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v11588; }
    { const char * tb_v11589 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v11589; }
    { const char * tb_v11590 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v11590; }
    { const char * tb_v11591 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v11591; }
    { const char * tb_v11592 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v11592; }
    { const char * tb_v11593 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11593; }
    { const char * tb_v11594 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11594; }
    { const char * tb_v11595 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v11595; }
    { const char * tb_v11596 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v11596; }
    { const char * tb_v11597 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v11597; }
    { const char * tb_v11598 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v11598; }
    { const char * tb_v11599 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v11599; }
    { const char * tb_v11600 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v11600; }
    { const char * tb_v11601 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v11601; }
    { const char * tb_v11602 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v11602; }
    { const char * tb_v11603 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v11603; }
    { const char * tb_v11604 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v11604; }
    { const char * tb_v11605 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v11605; }
    { const char * tb_v11606 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v11606; }
    { const char * tb_v11607 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v11607; }
    { const char * tb_v11608 = "typedef struct { int parent, useq; double piv[3], rot[3], mv[3], q[4]; } tb_bone_t;   // кость: родитель, сустав, поворот (или кватернион q, useq), сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v11608; }
    { const char * tb_v11609 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v11609; }
    { const char * tb_v11610 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v11610; }
    { const char * tb_v11611 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v11611; }
    { const char * tb_v11612 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v11612; }
