    { const char * tb_v11615 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw;\n"; *(const char * *)tb_grow(v_lines) = tb_v11615; }
    { const char * tb_v11616 = "    int shp, shc, shok; float shv[16]; int shimg[4]; int noshadow; float *shvd; long long shvn, shvcap, shused; void *shvb;\n"; *(const char * *)tb_grow(v_lines) = tb_v11616; }
    { const char * tb_v11617 = "    long long lod; double lodd, far, ub[4]; int hasub; } tb_mesh;   // lod — сетка вместо этой дальше lodd; far — дальше не рисовать; ub — свой шар (mesh_bounds)   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v11617; }
    { const char * tb_v11618 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11618; }
    { const char * tb_v11619 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11619; }
    { const char * tb_v11620 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v11620; }
