    { const char * tb_v11645 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11645; }
    { const char * tb_v11646 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11646; }
