    { const char * tb_v11732 = "// картинка для сетки: её треугольники из mesh_add_uv рисуются ею (остальные — своим цветом); -1 — без картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v11732; }
    { const char * tb_v11733 = "TB_API void tb_mesh_image(long long id, long long img) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11733; }
    { const char * tb_v11734 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11734; }
    { const char * tb_v11735 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11735; }
