    { const char * tb_v11739 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11739; }
    { const char * tb_v11740 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11740; }
    { const char * tb_v11741 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11741; }
    { const char * tb_v11742 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11742; }
    { const char * tb_v11743 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v11743; }
    { const char * tb_v11744 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v11744; }
    { const char * tb_v11745 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v11745; }
    { const char * tb_v11746 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v11746; }
    { const char * tb_v11747 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11747; }
    { const char * tb_v11748 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11748; }
