    { const char * tb_v11750 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11750; }
    { const char * tb_v11751 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v11751; }
    { const char * tb_v11752 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11752; }
    { const char * tb_v11753 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11753; }
    { const char * tb_v11754 = "// ---- свет: одно солнце (направление к нему) и фон; яркость грани — от того, как она повёрнута к солнцу ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11754; }
    { const char * tb_v11755 = "// Всё в целых, одной формулой на процессоре и на видеокарте (tb3.vert, tb3.metal): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v11755; }
    { const char * tb_v11756 = "TB_API double tb_lt[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v11756; }
    { const char * tb_v11757 = "TB_API int tb_lamb = -1;   // фон × 256; -1 — света нет, цвета как есть\n"; *(const char * *)tb_grow(v_lines) = tb_v11757; }
    { const char * tb_v11758 = "TB_API double tb_amb0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11758; }
    { const char * tb_v11759 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11759; }
    { const char * tb_v11760 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11760; }
    { const char * tb_v11761 = "    double l = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v11761; }
    { const char * tb_v11762 = "    // light(0, 0, 0, ...) — выключить солнце; фон остаётся для ламп (point_light, spot_light)\n"; *(const char * *)tb_grow(v_lines) = tb_v11762; }
    { const char * tb_v11763 = "    if (!(l > 1e-12)) { tb_lamb = -1; tb_amb0 = amb > 0 ? (amb < 1 ? amb : 1) : 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11763; }
    { const char * tb_v11764 = "    tb_lt[0] = dx / l; tb_lt[1] = dy / l; tb_lt[2] = dz / l;\n"; *(const char * *)tb_grow(v_lines) = tb_v11764; }
    { const char * tb_v11765 = "    if (!(amb > 0)) amb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11765; }
    { const char * tb_v11766 = "    if (amb > 1) amb = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11766; }
    { const char * tb_v11767 = "    tb_lamb = (int)tb_rnd(amb * 256);\n"; *(const char * *)tb_grow(v_lines) = tb_v11767; }
    { const char * tb_v11768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11768; }
    { const char * tb_v11769 = "// нормали треугольников: (b - a) × (c - a), длина 2^14. У куба, где грани по кругу против часовой\n"; *(const char * *)tb_grow(v_lines) = tb_v11769; }
    { const char * tb_v11770 = "// стрелки снаружи, нормаль смотрит наружу\n"; *(const char * *)tb_grow(v_lines) = tb_v11770; }
    { const char * tb_v11771 = "static void tb_mesh_normals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11771; }
    { const char * tb_v11772 = "    if (m->nrmok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11772; }
    { const char * tb_v11773 = "    m->nrmok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11773; }
    { const char * tb_v11774 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11774; }
    { const char * tb_v11775 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11775; }
    { const char * tb_v11776 = "        const double *a = m->v + 3 * m->t[3 * t], *b = m->v + 3 * m->t[3 * t + 1], *c = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11776; }
    { const char * tb_v11777 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11777; }
    { const char * tb_v11778 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11778; }
    { const char * tb_v11779 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11779; }
    { const char * tb_v11780 = "        for (int k = 0; k < 3; k++) m->nrm[3 * t + k] = l > 1e-300 ? (int32_t)tb_rnd(n[k] / l * 16384) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11780; }
    { const char * tb_v11781 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11781; }
    { const char * tb_v11782 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11782; }
    { const char * tb_v11783 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v11783; }
    { const char * tb_v11784 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v11784; }
    { const char * tb_v11785 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11785; }
    { const char * tb_v11786 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11786; }
    { const char * tb_v11787 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11787; }
    { const char * tb_v11788 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v11788; }
    { const char * tb_v11789 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11789; }
    { const char * tb_v11790 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v11790; }
    { const char * tb_v11791 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v11791; }
    { const char * tb_v11792 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v11792; }
    { const char * tb_v11793 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11793; }
    { const char * tb_v11794 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v11794; }
    { const char * tb_v11795 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11795; }
    { const char * tb_v11796 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v11796; }
    { const char * tb_v11797 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v11797; }
    { const char * tb_v11798 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v11798; }
    { const char * tb_v11799 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v11799; }
    { const char * tb_v11800 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v11800; }
    { const char * tb_v11801 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v11801; }
    { const char * tb_v11802 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11802; }
    { const char * tb_v11803 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11803; }
    { const char * tb_v11804 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11804; }
    { const char * tb_v11805 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11805; }
    { const char * tb_v11806 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v11806; }
    { const char * tb_v11807 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v11807; }
    { const char * tb_v11808 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11808; }
    { const char * tb_v11809 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11809; }
    { const char * tb_v11810 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11810; }
    { const char * tb_v11811 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v11811; }
    { const char * tb_v11812 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v11812; }
    { const char * tb_v11813 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11813; }
    { const char * tb_v11814 = "TB_API long long tb_3vcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11814; }
    { const char * tb_v11815 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v11815; }
    { const char * tb_v11816 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v11816; }
    { const char * tb_v11817 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11817; }
    { const char * tb_v11818 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v11818; }
    { const char * tb_v11819 = "TB_INL int tb_tex_on(const tb_mesh *m, long long t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11819; }
    { const char * tb_v11820 = "    return m->tex >= 0 && m->uv && !__builtin_isnan(m->uv[6 * t]) && (!tb_gpu_on || tb_gpu_tex);\n"; *(const char * *)tb_grow(v_lines) = tb_v11820; }
    { const char * tb_v11821 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11821; }
    { const char * tb_v11822 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v11822; }
