    { const char * tb_v12068 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v12068; }
    { const char * tb_v12069 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12069; }
    { const char * tb_v12070 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v12070; }
