    { const char * tb_v12562 = "typedef struct { long long id; double R[3][3], P[3]; double shine, glow; int alpha, sh; double *bm, *wp, *wn; } tb_srec;   // sh — сетка со своим шейдером\n"; *(const char * *)tb_grow(v_lines) = tb_v12562; }
