    { const char * tb_v13889 = "    char *s = tb_tmem((size_t)tb_ntyped + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13889; }
    { const char * tb_v13890 = "    memcpy(s, tb_typed, (size_t)tb_ntyped);\n"; *(const char * *)tb_grow(v_lines) = tb_v13890; }
