    { const char * tb_v13895 = "// буфер обмена системы: текст, который копируют и вставляют между программами (Cmd/Ctrl+C, V)\n"; *(const char * *)tb_grow(v_lines) = tb_v13895; }
    { const char * tb_v13896 = "TB_API const char *tb_clipboard_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13896; }
    { const char * tb_v13897 = "    char *got = tb_gfx_clip_get();   // malloc или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v13897; }
    { const char * tb_v13898 = "    size_t n = got ? strlen(got) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13898; }
    { const char * tb_v13899 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13899; }
    { const char * tb_v13900 = "    if (n) memcpy(s, got, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v13900; }
