    { const char * tb_v13905 = "TB_API void tb_clipboard_set(const char *s) { tb_gfx_clip_set(s ? s : \"\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13905; }
    { const char * tb_v13906 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v13906; }
    { const char * tb_v13907 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13907; }
    { const char * tb_v13908 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v13908; }
    { const char * tb_v13909 = "    for (int i = 0; i < 8; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v13909; }
    { const char * tb_v13910 = "        if (strcmp(name, names[i]) == 0) { tb_cursor_prog = i; if (tb_px) { if (!tb_mlock) tb_gfx_cursor(i); } else tb_cursor_want = i; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13910; }
    { const char * tb_v13911 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v13911; }
    { const char * tb_v13912 = "    snprintf(buf, sizeof buf, \"set_cursor: нет курсора «%s»; есть arrow, hand, text, move, resize_x, resize_y, wait, none\", name);\n"; *(const char * *)tb_grow(v_lines) = tb_v13912; }
    { const char * tb_v13913 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v13913; }
    { const char * tb_v13914 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13914; }
    { const char * tb_v13915 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v13915; }
    { const char * tb_v13916 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v13916; }
    { const char * tb_v13917 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v13917; }
    { const char * tb_v13918 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v13918; }
    { const char * tb_v13919 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v13919; }
    { const char * tb_v13920 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v13920; }
    { const char * tb_v13921 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v13921; }
    { const char * tb_v13922 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v13922; }
    { const char * tb_v13923 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v13923; }
    { const char * tb_v13924 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v13924; }
    { const char * tb_v13925 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v13925; }
    { const char * tb_v13926 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v13926; }
    { const char * tb_v13927 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v13927; }
    { const char * tb_v13928 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v13928; }
    { const char * tb_v13929 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v13929; }
    { const char * tb_v13930 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v13930; }
    { const char * tb_v13931 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v13931; }
    { const char * tb_v13932 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v13932; }
    { const char * tb_v13933 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v13933; }
    { const char * tb_v13934 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v13934; }
    { const char * tb_v13935 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v13935; }
    { const char * tb_v13936 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v13936; }
    { const char * tb_v13937 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v13937; }
    { const char * tb_v13938 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13938; }
    { const char * tb_v13939 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v13939; }
    { const char * tb_v13940 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v13940; }
    { const char * tb_v13941 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v13941; }
    { const char * tb_v13942 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v13942; }
    { const char * tb_v13943 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v13943; }
    { const char * tb_v13944 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v13944; }
    { const char * tb_v13945 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v13945; }
    { const char * tb_v13946 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v13946; }
    { const char * tb_v13947 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v13947; }
    { const char * tb_v13948 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v13948; }
    { const char * tb_v13949 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v13949; }
    { const char * tb_v13950 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13950; }
    { const char * tb_v13951 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13951; }
    { const char * tb_v13952 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v13952; }
    { const char * tb_v13953 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v13953; }
    { const char * tb_v13954 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13954; }
    { const char * tb_v13955 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13955; }
    { const char * tb_v13956 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13956; }
    { const char * tb_v13957 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13957; }
    { const char * tb_v13958 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13958; }
    { const char * tb_v13959 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13959; }
    { const char * tb_v13960 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v13960; }
    { const char * tb_v13961 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13961; }
    { const char * tb_v13962 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v13962; }
    { const char * tb_v13963 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13963; }
    { const char * tb_v13964 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v13964; }
    { const char * tb_v13965 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v13965; }
    { const char * tb_v13966 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v13966; }
    { const char * tb_v13967 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v13967; }
    { const char * tb_v13968 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v13968; }
    { const char * tb_v13969 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v13969; }
    { const char * tb_v13970 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13970; }
    { const char * tb_v13971 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13971; }
    { const char * tb_v13972 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v13972; }
    { const char * tb_v13973 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v13973; }
    { const char * tb_v13974 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13974; }
    { const char * tb_v13975 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v13975; }
    { const char * tb_v13976 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13976; }
    { const char * tb_v13977 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13977; }
    { const char * tb_v13978 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v13978; }
    { const char * tb_v13979 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13979; }
    { const char * tb_v13980 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13980; }
    { const char * tb_v13981 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v13981; }
    { const char * tb_v13982 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13982; }
    { const char * tb_v13983 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v13983; }
    { const char * tb_v13984 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v13984; }
    { const char * tb_v13985 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13985; }
    { const char * tb_v13986 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13986; }
    { const char * tb_v13987 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v13987; }
    { const char * tb_v13988 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v13988; }
    { const char * tb_v13989 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13989; }
    { const char * tb_v13990 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v13990; }
    { const char * tb_v13991 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v13991; }
    { const char * tb_v13992 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v13992; }
    { const char * tb_v13993 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v13993; }
    { const char * tb_v13994 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v13994; }
    { const char * tb_v13995 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v13995; }
    { const char * tb_v13996 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13996; }
    { const char * tb_v13997 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13997; }
    { const char * tb_v13998 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v13998; }
    { const char * tb_v13999 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v13999; }
    { const char * tb_v14000 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v14000; }
    { const char * tb_v14001 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
    { const char * tb_v14010 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14010; }
    { const char * tb_v14011 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14011; }
    { const char * tb_v14012 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14012; }
    { const char * tb_v14013 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14013; }
    { const char * tb_v14014 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14014; }
    { const char * tb_v14015 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v14015; }
    { const char * tb_v14016 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14016; }
    { const char * tb_v14017 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
    { const char * tb_v14020 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v14020; }
    { const char * tb_v14021 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14021; }
    { const char * tb_v14022 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v14022; }
    { const char * tb_v14023 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
