    { const char * tb_v14269 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14269; }
    { const char * tb_v14270 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14270; }
    { const char * tb_v14271 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14271; }
    { const char * tb_v14272 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14272; }
    { const char * tb_v14273 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v14273; }
