    { const char * tb_v14285 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14285; }
    { const char * tb_v14286 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v14286; }
    { const char * tb_v14287 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14287; }
    { const char * tb_v14288 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14288; }
    { const char * tb_v14289 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v14289; }
    { const char * tb_v14290 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14290; }
