    { const char * tb_v14353 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v14353; }
    { const char * tb_v14354 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14354; }
    { const char * tb_v14355 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14355; }
    { const char * tb_v14356 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v14356; }
    { const char * tb_v14357 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v14357; }
