    { const char * tb_v14359 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14359; }
    { const char * tb_v14360 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v14360; }
