    { const char * tb_v14366 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v14366; }
    { const char * tb_v14367 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14367; }
